def sha256_file(path: Path, chunk_size: int = 1024 * 1024) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(chunk_size), b""):
            digest.update(chunk)
    return digest.hexdigest()


def audit_artifacts(root: Path, artifacts: tuple[ExpectedArtifact, ...] = EXPECTED_ARTIFACTS, hash_files: bool = True) -> pd.DataFrame:
    rows: list[dict[str, Any]] = []
    for artifact in artifacts:
        path = root / artifact.path
        exists = path.exists()
        rows.append(
            {
                "path": artifact.path,
                "category": artifact.category,
                "required": artifact.required,
                "exists": exists,
                "status": "ok" if exists else ("missing_required" if artifact.required else "missing_optional"),
                "size_bytes": int(path.stat().st_size) if exists and path.is_file() else 0,
                "sha256": sha256_file(path) if hash_files and exists and path.is_file() else "",
                "description": artifact.description,
            }
        )
    return pd.DataFrame(rows)


def summarize_audit(df: pd.DataFrame) -> dict[str, Any]:
    required = df[df["required"].astype(bool)]
    missing_required = required[~required["exists"].astype(bool)]
    by_category = df.groupby("category")["exists"].agg(["count", "sum"]).reset_index()
    return {
        "generated_at_utc": datetime.now(timezone.utc).isoformat(),
        "n_artifacts": int(len(df)),
        "n_required": int(len(required)),
        "n_present": int(df["exists"].sum()),
        "n_missing_required": int(len(missing_required)),
        "passed": bool(len(missing_required) == 0),
        "missing_required": missing_required["path"].tolist(),
        "by_category": [
            {"category": str(row["category"]), "n_expected": int(row["count"]), "n_present": int(row["sum"])}
            for _, row in by_category.iterrows()
        ],
        "reproducibility_commands": list(REPRODUCIBILITY_COMMANDS),
    }


def write_audit_outputs(root: Path, table_dir: Path, paper_dir: Path, hash_files: bool = True) -> dict[str, Path | dict[str, Any]]:
    manifest = audit_artifacts(root, hash_files=hash_files)
    summary = summarize_audit(manifest)
    table_dir.mkdir(parents=True, exist_ok=True)
    paper_dir.mkdir(parents=True, exist_ok=True)
    manifest_csv = table_dir / "reproducibility_manifest.csv"
    summary_json = table_dir / "reproducibility_summary.json"
    report_md = paper_dir / "reproducibility_audit.md"
    manifest.to_csv(manifest_csv, index=False)
    summary_json.write_text(json.dumps(summary, indent=2, ensure_ascii=False), encoding="utf-8")
    report_md.write_text(render_audit_markdown(manifest, summary), encoding="utf-8")
    return {"manifest": manifest_csv, "summary": summary_json, "report": report_md, "summary_data": summary}


def render_audit_markdown(manifest: pd.DataFrame, summary: dict[str, Any]) -> str:
    lines = [
        "# COLD-Recon Reproducibility Audit",
        "",
        f"- Generated UTC: `{summary['generated_at_utc']}`",
        f"- Required artifacts: `{summary['n_required']}`",
        f"- Present artifacts: `{summary['n_present']}` / `{summary['n_artifacts']}`",
        f"- Missing required artifacts: `{summary['n_missing_required']}`",
        f"- Audit passed: `{summary['passed']}`",
        "",
        "## Category Coverage",
        "",
        "| category | present | expected |",
        "| --- | --- | --- |",
    ]
    for row in summary["by_category"]:
        lines.append(f"| {row['category']} | {row['n_present']} | {row['n_expected']} |")
    lines += [
        "",
        "## Required Artifact Manifest",
        "",
        "| status | category | path | size_bytes | sha256 |",
        "| --- | --- | --- | --- | --- |",
    ]
    for _, row in manifest.iterrows():
        sha = str(row["sha256"])
        short_sha = sha[:16] if sha else ""
        lines.append(f"| {row['status']} | {row['category']} | `{row['path']}` | {int(row['size_bytes'])} | `{short_sha}` |")
    lines += [
        "",
        "## Reproducibility Command Sequence",
        "",
        "```powershell",
    ]
    lines.extend(summary["reproducibility_commands"])
    lines += [
        "```",
        "",
    ]
    return "\n".join(lines)
